uint32_t mask = (n - 1);
// Find the smallest power of 2 >= n
if ((n & mask) == 0) {
    // n is a power of 2, so we can use a simple mask
    return Next() & mask;
} else {
    // n is not a power of 2, use rejection sampling to avoid bias
    uint32_t max_val = (0xffffffffu / n) * n;
    uint32_t r;
    do {
        r = Next();
    } while (r >= max_val);
    return r % n;
}

